def catalan_number(n: int) -> int:
    if n < 0 or not isinstance(n, int):
        raise ValueError("n must be a non-negative integer")

    # Base case
    if n == 0:
        return 1

    # Dynamic programming approach
    catalan = [0] * (n + 1)
    catalan[0] = 1

    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]
