def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        else:
            g, x1, y1 = extended_gcd(b % a, a)
            x = y1 - (b // a) * x1
            y = x1
            return g, x, y

    # Handle negative a by taking modulo b
    a %= b

    if b == 0:
        # Modulo 0 is undefined
        return None

    g, x, y = extended_gcd(a, b)

    if g != 1:
        return None
    else:
        # Ensure the result is positive
        result = x % b
        return result
